
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ms2b_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ms2b", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.682522954430971e+00, -4.589741771402555e+00, -4.459759461096991e+00, -4.279757905342841e+00, -4.034603454928195e+00, -3.708583564240744e+00, -3.289540802412043e+00, -2.776343004644010e+00, -2.188810815609056e+00, -1.571586769083432e+00, -1.007055675661193e+00, -6.914547895008087e-01, -6.016079824545123e-01, -5.142015841405239e-01, -3.685744237543879e-01, -2.257081245412214e-01, -1.147122316500770e-01, -4.141904821863495e-02, -9.015229815609685e-03, -1.013953113780004e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


